#include <cstdio>
#include <vector>

int main() {
    int N;

    while (scanf("%d", &N), N) { // Combining input reading and condition check
        std::vector<int> k(N), kk(N, 0);
        for (int i = 0; i < N; ++i)
            scanf("%d", &k[i]);

        int i = 0, c = 0;
        while (i <= N * 2) { // Adjusted loop condition to avoid unnecessary checks
            if (k[i % N] > 0) {
                k[i % N]--;
                kk[i % N]++;
                c++;
            }
            if (kk[i % N] == 2) {
                printf("%d\n", c);
                break;
            }
            i++;
        }
        if (i > N * 2) // Moved the check outside to avoid unnecessary checks in the loop
            printf("NA\n");
    }
    return 0;
}

